(function(){
  const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const toast=(message)=>{let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.appendChild(el)}el.textContent=message;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),1800)};
  $$('[data-toast]').forEach(el=>el.addEventListener('click',()=>toast(el.dataset.toast)));
  const closeModal=(modal)=>{if(!modal)return;modal.classList.remove('open');modal._returnFocus?.focus()};
  const openModal=(trigger)=>{const modal=$('#'+trigger.dataset.openModal);if(!modal)return;modal._returnFocus=trigger;modal.classList.add('open');const target=$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])',modal);requestAnimationFrame(()=>target?.focus())};
  $$('[data-open-modal]').forEach(el=>el.addEventListener('click',()=>openModal(el)));
  $$('[data-close-modal]').forEach(el=>el.addEventListener('click',()=>closeModal(el.closest('.modal'))));
  $$('.modal').forEach(el=>{const dialog=$('.dialog',el);if(dialog){dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true')}el.addEventListener('click',e=>{if(e.target===el)closeModal(el)})});
  $$('[data-secret-toggle]').forEach(btn=>btn.addEventListener('click',()=>{const target=$('#'+btn.dataset.secretToggle);if(!target)return;const hidden=target.dataset.hidden!=='false';target.dataset.hidden=String(!hidden);target.textContent=hidden?(target.dataset.value||'示例内容已隐藏'):'••••••••••••';btn.textContent=hidden?'隐藏':'显示'}));
  $$('[data-choice]').forEach(el=>el.addEventListener('click',()=>{const group=el.parentElement;$$('[data-choice]',group).forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}));
  const importBtn=$('#saveProfileBtn'); if(importBtn) importBtn.addEventListener('click',()=>{const input=$('#claimCode');const msg=$('#importMessage');if(!input.value.trim()){msg.className='notice warning';msg.innerHTML='<strong>尚未粘贴 T-key</strong><span>请粘贴完整 T-key 或 sfsc:// 导入 URI。</span>';return}msg.className='notice success';msg.innerHTML='<strong>连接检查通过</strong><span>Profile 已保存；示例原型不会提交或保留输入内容。</span>';setTimeout(()=>location.href='client-sync.html',650)});
  const run=$('#runSyncBtn'),stop=$('#stopSyncBtn'),bar=$('#progressFill'),value=$('#progressValue'),syncState=$('#syncStatus'),stage=$('#syncStage');let timer=null,progress=0;
  if(run)run.addEventListener('click',()=>{progress=12;run.disabled=true;stop.disabled=false;syncState.className='status syncing';syncState.textContent='同步中';stage.textContent='正在比较文件';bar.style.width=progress+'%';value.textContent=progress+'%';timer=setInterval(()=>{progress=Math.min(92,progress+7);bar.style.width=progress+'%';value.textContent=progress+'%';if(progress>55)stage.textContent='正在传输文件'},600)});
  if(stop)stop.addEventListener('click',()=>{clearInterval(timer);syncState.textContent='正在停止';stage.textContent='等待当前文件安全停止';stop.disabled=true;setTimeout(()=>{syncState.className='status';syncState.textContent='已停止';stage.textContent='同步已停止';run.disabled=false;toast('同步已停止')},900)});
  const confirmInput=$('#confirmTextInput'),confirmSubmit=$('#confirmSubmitBtn');if(confirmInput&&confirmSubmit){confirmInput.addEventListener('input',()=>confirmSubmit.disabled=confirmInput.value!=='DELETE');confirmSubmit.addEventListener('click',e=>{e.preventDefault();confirmInput.closest('.modal').classList.remove('open');toast('操作已确认（原型未执行）')})}
  const historyFilter=$('#historyStatusFilter');if(historyFilter)historyFilter.addEventListener('change',()=>{$$('tbody tr[data-state]').forEach(row=>row.hidden=historyFilter.value&&row.dataset.state!==historyFilter.value)});
  const deviceSearch=$('#deviceSearch');if(deviceSearch)deviceSearch.addEventListener('input',()=>{const q=deviceSearch.value.trim().toLowerCase();$$('tbody tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.toLowerCase().includes(q))});
  const generate=$('#createClaimBtn');if(generate)generate.addEventListener('click',()=>{const box=$('#claimResult');box.classList.remove('hidden');$('#claimMasked').textContent='SFSC1-••••-••••-••••';toast('已生成一次性 T-key 示例')});
  const login=$('#loginForm');if(login)login.addEventListener('submit',e=>{e.preventDefault();const input=$('#adminTokenInput');const msg=$('#authMessage');if(!input.value){msg.textContent='请输入管理 Token';msg.style.color='var(--danger)';return}location.href='server-overview.html'});
  window.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal.open').forEach(closeModal)});
})();
